import numpy as np
from scipy.optimize import minimize
import sys

# Standard SLSQP functions
def pack_to_z(c, r):
    z = np.zeros(26*3); z[0::3], z[1::3], z[2::3] = c[:,0], c[:,1], r; return z
def z_to_pack(z):
    c = np.vstack((z[0::3], z[1::3])).T; r = z[2::3]; return c, r
def objective(z): return -np.sum(z[2::3])
def constraint_boundary(z):
    c, r = z_to_pack(z); return np.concatenate((c[:,0]-r, 1-c[:,0]-r, c[:,1]-r, 1-c[:,1]-r))
def constraint_nonoverlap(z):
    c, r = z_to_pack(z); pdist_sq = np.sum((c[:,None,:]-c[None,:,:])**2, axis=-1)
    r_sum = r[:,None] + r[None,:]; iu = np.triu_indices(26, k=1); return np.sqrt(pdist_sq[iu] + 1e-12) - r_sum[iu]
def generate_systematic_grid_hole_seed():
    grid_coords = np.array([0.1, 0.3, 0.5, 0.7, 0.9]); r0 = 0.1 - 1e-8
    centers = np.array([[x, y] for x in grid_coords for y in grid_coords]); radii = np.full(25, r0)
    i, j = (0,1); cx = (grid_coords[i]+grid_coords[i+1])/2.0; cy = (grid_coords[j]+grid_coords[j+1])/2.0
    hole_center = np.array([cx, cy]); corner = np.array([grid_coords[i], grid_coords[j]])
    dist = np.linalg.norm(hole_center - corner); r_hole = dist - r0
    return np.vstack([centers, hole_center]), np.append(radii, r_hole)
def perturb_centers(centers, magnitude):
    delta = np.random.uniform(-magnitude, magnitude, size=(26, 2))
    return np.clip(centers + delta, 1e-6, 1 - 1e-6)

def construct_packing():
    N = 26
    perturbation_magnitudes = np.linspace(0.01, 0.1, 10) # Wide sweep
    num_trials_per_magnitude = 10 # High number of trials

    best_overall_score = -1.0
    best_packing_z = None

    sota_base_centers, _ = generate_systematic_grid_hole_seed()

    for mag in perturbation_magnitudes:
        for trial in range(num_trials_per_magnitude):
            np.random.seed(int(mag * 1000) + trial) 
            perturbed_centers = perturb_centers(sota_base_centers, mag)

            initial_radii = np.full(N, 0.05)
            z0 = pack_to_z(perturbed_centers, initial_radii)

            bounds = [(0,1) if i%3!=2 else (1e-6,0.5) for i in range(N*3)]
            constraints = [{'type':'ineq','fun':constraint_boundary}, {'type':'ineq','fun':constraint_nonoverlap}]
            res = minimize(objective, z0, method='SLSQP', bounds=bounds, constraints=constraints, options={'maxiter':500,'ftol':1e-9})

            if res.success and -res.fun > best_overall_score:
                best_overall_score = -res.fun
                best_packing_z = res.x

    if best_packing_z is None: return sota_base_centers, np.full(N, 0.05)

    final_centers, final_radii = z_to_pack(best_packing_z)
    return final_centers, final_radii * (1.0 - 1e-9)
